/**
 * Stretch guide for the exercise mirror (SRS-RHB-016): the current step's hand contacts drawn on the user's own face.
 * Blue is where the fixing hand holds; orange runs from start to full stretch, with the point where the fingers
 * should be now on the exercise timeline (rehab/motion.ts).
 *
 * The contacts are in the eye-local system of face.ts (ELC). The ELC frame is set on the rest reference, taken
 * before the hands come in. Each live frame is then followed with the measurement's robust similarity
 * (core restOnLive), which keeps the anchors that still agree. A hand covering part of the face therefore does not
 * move the guide, as long as enough anchors stay visible.
 */
import { SIDE, restOnLive, type FrameObservation, type RestReference, type Side, type Vec2 } from '../core';
import type { Pt } from './face';
import type { Scene } from './motion';
import { isFixed, type Contact } from './stretches';
import { josa } from '../core/josa';

export interface ElcFrame {
  origin: Vec2;
  /** Unit vectors towards the affected ear and up the face (image pixels). */
  ex: Vec2;
  ey: Vec2;
  /** Half the palpebral width of the affected eye (pixels). */
  unit: number;
}

/** ELC on a landmark set: origin at the affected eye's centre, x towards that ear, y up, unit = half the eye width. */
export function elcFrame(px: readonly Vec2[], affected: Side): ElcFrame {
  const inner = px[SIDE[affected].eyeInner]!;
  const outer = px[SIDE[affected].eyeOuter]!;
  const dx = outer.x - inner.x;
  const dy = outer.y - inner.y;
  const len = Math.hypot(dx, dy);
  const ex = { x: dx / len, y: dy / len };
  // The perpendicular that points up the image (towards the forehead) for an upright face.
  const ey = ex.x >= 0 ? { x: ex.y, y: -ex.x } : { x: -ex.y, y: ex.x };
  return { origin: { x: (inner.x + outer.x) / 2, y: (inner.y + outer.y) / 2 }, ex, ey, unit: len / 2 };
}

export const elcToPx = (f: ElcFrame, [x, y]: Pt): Vec2 => ({
  x: f.origin.x + f.unit * (x * f.ex.x + y * f.ey.x),
  y: f.origin.y + f.unit * (x * f.ex.y + y * f.ey.y),
});

export interface StretchMark {
  hand: 'A' | 'B';
  /** No movement: this contact holds the skin. */
  fixing: boolean;
  intraoral: boolean;
  label: Contact['label'];
  /** Contact at rest, at full stretch, and where it should be now (live image pixels). */
  start: Vec2;
  end: Vec2;
  now: Vec2;
}

/** The current step's contacts on one live frame; null without hands in the scene or without a face. */
export function stretchMarks(ref: RestReference, obs: FrameObservation, affected: Side, scene: Scene): StretchMark[] | null {
  if (!scene.step || scene.hands.length === 0 || scene.approach <= 0) return null;
  const f = elcFrame(ref.px, affected);
  const pts: Vec2[] = [];
  for (const { c, at } of scene.hands)
    pts.push(elcToPx(f, c.pos), elcToPx(f, [c.pos[0] + c.move[0], c.pos[1] + c.move[1]]), elcToPx(f, at));
  const mapped = restOnLive(ref, obs, pts);
  if (!mapped) return null;
  return scene.hands.map(({ c }, k) => ({
    hand: c.hand,
    fixing: isFixed(c),
    intraoral: !!c.intraoral,
    label: c.label,
    start: mapped.extra[3 * k]!,
    end: mapped.extra[3 * k + 1]!,
    now: mapped.extra[3 * k + 2]!,
  }));
}

/**
 * The massage stroke on one live frame (SRS-RHB-024): its path and where the fingertips are now, in live pixels. The
 * strokes are in the same eye-local system as the stretch contacts (motion.ts MASSAGE), on the affected side. Null
 * outside a stroke or without a face.
 */
export function massageMarks(ref: RestReference, obs: FrameObservation, affected: Side, scene: Scene): { path: Vec2[]; at: Vec2 } | null {
  const st = scene.stroke;
  if (scene.mode !== 'massage' || !st || st.path.length === 0) return null;
  const f = elcFrame(ref.px, affected);
  const mapped = restOnLive(ref, obs, [...st.path.map((p) => elcToPx(f, p)), elcToPx(f, st.at)]);
  if (!mapped) return null;
  return { path: mapped.extra.slice(0, st.path.length), at: mapped.extra[st.path.length]! };
}

/**
 * The hand landmarks (MediaPipe topology) standing for each contact label: the fingertip, or the palm's centre (wrist
 * and finger bases). SRS-RHB-032.
 */
const HAND_POINTS: Record<string, readonly number[]> = { 검지: [8], 중지: [12], 약지: [16], 엄지: [4], 손바닥: [0, 5, 9, 13, 17] };
/** A palm is broader than a fingertip: its tolerance is this many times larger. */
const PALM_TOL = 1.6;

/** Where a hand's part for a contact label is (mean of its landmarks); fingertips 8 and 12 for an unknown label. */
export function handPoint(hand: { pts: readonly Vec2[] }, label: string): Vec2 | null {
  const idx = HAND_POINTS[label] ?? [8, 12];
  const ps = idx.map((i) => hand.pts[i]).filter((q): q is Vec2 => !!q);
  if (!ps.length) return null;
  return { x: ps.reduce((a, q) => a + q.x, 0) / ps.length, y: ps.reduce((a, q) => a + q.y, 0) / ps.length };
}

/**
 * How far a hand may be from its contact and still count as on it (live pixels): a quarter of the distance between
 * the eye centres, about 16 mm. Null without a face.
 */
export function handTolerance(obs: FrameObservation): number | null {
  if (obs.landmarks.length < 468 * 3) return null;
  const p = (i: number): Vec2 => ({ x: obs.landmarks[3 * i]! * obs.width, y: obs.landmarks[3 * i + 1]! * obs.height });
  const mid = (a: Vec2, b: Vec2): Vec2 => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 });
  const r = mid(p(SIDE.right.eyeOuter), p(SIDE.right.eyeInner));
  const l = mid(p(SIDE.left.eyeOuter), p(SIDE.left.eyeInner));
  return 0.25 * Math.hypot(r.x - l.x, r.y - l.y);
}

/**
 * Whether each contact has a hand on it now (SRS-RHB-032): the matching finger or palm of either hand within `tol`
 * pixels of where it should be at this moment of the timeline. Contacts inside the mouth cannot be seen: null.
 */
export function contactsInPlace(
  marks: readonly StretchMark[],
  hands: readonly { pts: readonly Vec2[] }[],
  tol: number,
): (boolean | null)[] {
  return marks.map((m) => {
    if (m.intraoral) return null;
    const lim = m.label === '손바닥' ? tol * PALM_TOL : tol;
    return hands.some((h) => {
      const q = handPoint(h, m.label);
      return !!q && Math.hypot(q.x - m.now.x, q.y - m.now.y) <= lim;
    });
  });
}

/**
 * Whether any seen hand is near any contact, within `k` × the tolerance: the hands are on the face at all. The hold waits
 * only when hands are seen and none is near (lowered but still in view); a contact a little off only turns orange,
 * since on rendered demonstrator frames a seen hand was within 1 tolerance of its contact in about half of them
 * (BENCH.md). SRS-RHB-032.
 */
export const NEAR_TOL = 2;
export function handsNear(marks: readonly StretchMark[], hands: readonly { pts: readonly Vec2[] }[], tol: number, k = NEAR_TOL): boolean {
  return marks.some(
    (m) =>
      !m.intraoral &&
      hands.some((h) => {
        const q = handPoint(h, m.label);
        return !!q && Math.hypot(q.x - m.now.x, q.y - m.now.y) <= tol * k * (m.label === '손바닥' ? PALM_TOL : 1);
      }),
  );
}

/** Whether a fingertip (index or middle, either hand) is on the massage point within `k` × 1.3 × `tol` pixels (SRS-RHB-032). */
export function strokeFollowed(at: Vec2, hands: readonly { pts: readonly Vec2[] }[], tol: number, k = 1): boolean {
  return hands.some((h) => [8, 12].some((i) => !!h.pts[i] && Math.hypot(h.pts[i]!.x - at.x, h.pts[i]!.y - at.y) <= tol * 1.3 * k));
}

/** One line for the current phase, in the words the guide draws (blue holds, orange moves along the arrow). */
export function stretchCue(scene: Scene): string {
  if (!scene.step) return '파란 원과 주황 원이 손가락을 댈 곳입니다';
  const fix = scene.step.contacts.filter(isFixed);
  const move = scene.step.contacts.filter((c) => !isFixed(c));
  const fingers = (cs: Contact[]) => {
    const w = [...new Set(cs.map((c) => (c.intraoral ? `${c.label}(입안)` : c.label)))].join('·');
    return josa(w, '을/를');
  };
  switch (scene.phase.key) {
    case 'prepare':
      return [fix.length ? `파란 원에 ${fingers(fix)} 대고 고정` : '', move.length ? `주황 원에 ${fingers(move)} 대세요` : '']
        .filter(Boolean)
        .join(', ');
    case 'stretch':
      return '주황 화살표를 따라 천천히 늘리세요';
    case 'hold':
      return `그대로 ${Math.max(1, Math.ceil(scene.remaining))}초 유지`;
    case 'release':
      return '천천히 풀어 주세요';
    default:
      return '잠시 쉬세요';
  }
}
