import { actions, useApp } from '../../data/store';
import { josa } from '../../core/josa';
import { FEEL_LABEL, type Feel } from '../../rehab/dose';
import { Notice } from './common';

/** "방금 운동은 어땠나요?" after an exercise; the answer sets the next dose (rehab/dose.ts). */
export function FeelPrompt({ logId, onAnswered }: { logId: string; onAnswered?: (f: Feel) => void }) {
  const { rehab } = useApp();
  const answered = rehab.find((r) => r.id === logId)?.feel;
  return (
    <div role="group" aria-label="운동 느낌" style={{ marginTop: '8px' }}>
      <div class="small ink2">
        방금 운동은 어땠나요?{' '}
        <span class="xsmall muted">{answered ? `${josa(FEEL_LABEL[answered], '으로/로')} 기록했습니다` : '다음 번 양 조절에 씁니다'}</span>
      </div>
      <div class="row wrap" style={{ gap: '6px', marginTop: '6px' }}>
        {(Object.keys(FEEL_LABEL) as Feel[]).map((f) => (
          <button
            class={`btn sm ${answered === f ? 'primary' : ''}`}
            aria-pressed={answered === f}
            onClick={async () => {
              await actions.setFeel(logId, f);
              onAnswered?.(f);
            }}
          >
            {FEEL_LABEL[f]}
          </button>
        ))}
      </div>
      {answered === 'sore' && (
        <Notice tone="warn">
          <span class="small">아프거나 당기면 멈추고 쉬세요. 다음에는 양을 줄여 드리고, 계속되면 의료진과 상의하세요.</span>
        </Notice>
      )}
    </div>
  );
}
